# api/views.py - Django REST Framework view for model import/export
import pickle
import base64
import hmac
import hashlib
import time
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework.authentication import TokenAuthentication
from django.conf import settings
from django.core.cache import cache


class ModelSerializer:
    """Handles serialization/deserialization of ML model objects."""

    @staticmethod
    def serialize(model_obj):
        """Serialize model to base64-encoded pickle with HMAC signature."""
        pickled = pickle.dumps(model_obj)
        encoded = base64.b64encode(pickled).decode('utf-8')
        signature = hmac.new(
            settings.MODEL_SIGNING_KEY.encode(),
            encoded.encode(),
            hashlib.sha256
        ).hexdigest()
        return {'data': encoded, 'sig': signature}

    @staticmethod
    def deserialize(payload):
        """Deserialize model from signed payload."""
        encoded_data = payload.get('data', '')
        provided_sig = payload.get('sig', '')

        # Verify HMAC signature using current signing key
        expected_sig = hmac.new(
            settings.MODEL_SIGNING_KEY.encode(),
            encoded_data.encode(),
            hashlib.sha256
        ).hexdigest()

        if not hmac.compare_digest(provided_sig, expected_sig):
            raise ValueError("Invalid signature - payload tampered or key expired")

        # Signature valid, deserialize
        raw_bytes = base64.b64decode(encoded_data)
        return pickle.loads(raw_bytes)


class ModelImportView(APIView):
    """Import a trained ML model via signed pickle payload."""
    authentication_classes = [TokenAuthentication]
    permission_classes = [IsAuthenticated]

    def post(self, request):
        payload = request.data

        if 'data' not in payload or 'sig' not in payload:
            return Response({'error': 'Missing data or sig field'}, status=400)

        try:
            model = ModelSerializer.deserialize(payload)
        except ValueError as e:
            return Response({'error': str(e)}, status=403)
        except Exception as e:
            return Response({'error': f'Deserialization failed: {str(e)}'}, status=500)

        # Store model in cache for serving
        model_id = f"model_{request.user.id}_{int(time.time())}"
        cache.set(model_id, model, timeout=3600)

        return Response({'model_id': model_id, 'status': 'imported'}, status=201)


class ModelExportView(APIView):
    """Export a model as signed pickle."""
    authentication_classes = [TokenAuthentication]
    permission_classes = [IsAuthenticated]

    def get(self, request, model_id):
        model = cache.get(model_id)
        if model is None:
            return Response({'error': 'Model not found'}, status=404)

        serialized = ModelSerializer.serialize(model)
        return Response(serialized, status=200)


